/* Decisions — short records: the decision and why. Explanations live on the pages they link to.
   IDs are permanent, so gaps are expected. */
(function () {
  const { L, D, table, badge } = window.TDS;
  const A = 'Agreed', P = 'Proposed', O = 'Open', X = 'Deferred';

  const records = [
    { n: 66, s: A, t: 'Encryption key reuse defaults to the transaction; applications choose the tradeoff', link: ['python-encryption-retention'],
      body: `Transaction retention is the default, with exchange fallback in autocommit. Applications choose exchange scope or fixed-age reuse across transactions within one physical connection and exclusive pool lease, with independent local master/column settings and strict overrides. Hits never extend deadlines. Pool return/reset, context changes, failure/recovery and close clear/revoke keys. Expiry reloads without limiting transaction duration. Rust key-ownership development exposed the need to replace Python’s shared context cache (D-60). Python implements these choices in its SQL facade and clears owned mutable key buffers; Python/backend temporary copies and native provider memory remain outside that guarantee. Rust’s owned-key policy/lifecycle service is recorded in ${L('encryption-implementation', 'design N')}; transparent SQL encryption and independent .NET interoperability are recorded in ${L('rust-transparent-encryption', 'design O')}.`,
      why: 'The user requested explicit efficiency/security tradeoffs after examining repeated key work during Rust development.' },
    { n: 1, s: A, t: 'Documentation approach', body: 'Organize the docs by learning-science principles: Model → Worked Example → Reference → Decisions → Done When. Code and runtime observability use the same model and names.',
      why: 'Readers learn the overall structure first, then add the details to it. One model expressed three times is learned once.' },
    { n: 2, s: A, t: 'Protocol versions', body: 'TDS 7.4 and 8.0 only. Login fails with a clear error on anything lower.',
      why: 'This covers SQL Server 2012–2025 and Azure SQL, and leaves one message grammar to describe.' },
    { n: 3, s: A, t: 'Scope order', body: 'Client first; the proxy is on the backlog. Design is agreed before any code, and before choosing a language.' },
    { n: 4, s: A, t: 'Optimized mode exists', body: `The client can run without collecting observability data. The levels are ${D(12)}.` },
    { n: 5, s: A, t: 'One documentation set', body: '<code>docs/design/</code> is the single design set. Anything still useful in the earlier SDD spec draft was moved into it, and the draft was removed. The first structure summary, <code>docs/tds-common-structure.md</code>, was removed on 2026-10-16, once the Requests and Request Response pages replaced its request-phase content.' },
    { n: 17, s: A, t: 'The connection manager owns setup and everything shared', link: ['client', '3-connections-and-serial-channels'],
      body: 'It is the only code that knows the TLS version or whether MARS is in use. It handles TCP, TLS, hello, login and MARS, and it owns what serial channels share: session state, fatal errors, and per-channel buffering under MARS.',
      why: 'Setup is a different kind of work from requests. Keeping it in one place makes both halves easier to read.' },
    { n: 18, s: A, t: 'Client code asks for a serial channel; MARS only changes how many',
      body: 'Client code is identical with or without MARS. Without MARS a connection allows one serial channel; with MARS it allows several, which take turns and share the connection’s transaction and settings. Parallel work needs separate connections, and the interface’s structure makes this plain. MARS changes how many channels a connection offers. It never changes who shares that connection’s session (D-36).',
      why: 'MARS gives interleaving, not parallelism.' },
    { n: 19, s: A, t: 'The name is serial_channel', body: '',
      why: 'It states the property that matters: “connections are parallel; serial channels are not.” It also avoids confusion with <i>token stream</i>.' },
    { n: 20, s: A, t: 'One serial channel too many fails immediately', body: 'The serial channel already open, and the connection, are unaffected.' },
    { n: 21, s: A, t: 'Serial channels are handed out, each with one owner',
      body: 'A serial channel is owned by the task that opened it, scoped to a block, and can be handed to another task explicitly. Use from any other task fails immediately. A synchronous wrapper checks the owning thread instead. This remains the Python contract; D-64 records the user-selected proposal for movable Rust authority.',
      why: 'Misuse then fails every time, not only when calls happen to overlap. <b>Rejected:</b> a single switchable pipe, because of its hidden “current channel” mode; and hand-out without owners, because misuse would depend on timing.' },
    { n: 22, s: A, t: 'A new request while a response is open fails immediately', body: 'It is never queued. Cancel is the exception.',
      why: `The rule itself is TDS’s (${L('model', 'Model, rule 1', 'rules-that-hold-everywhere')}); failing at once keeps misuse visible.` },
    { n: 23, s: A, t: 'Only the owner sends and reads; anyone may cancel or close', body: '',
      why: 'A watchdog, a cancel button or runtime cleanup may run on another task. Cancel and close are safe to repeat and never interleave with the owner’s data.' },
    { n: 27, s: A, t: 'Teaching surfaces and machinery', link: ['client', '1-two-kinds-of-code'],
      body: 'Definitions, procedures and observability output must read as plainly as the reference pages, and they hold all protocol knowledge. The engine holds none: it is small, its invariants are written down, it is fuzzed, and it holds every bounds check. Every surface element carries its MS-TDS section and the spec revision it was checked against.',
      why: 'A security analyst can validate the code, a new developer can start work without reading MS-TDS, and a new MS-TDS release’s Change Tracking table maps directly onto what must change.' },
    { n: 29, s: A, t: 'The website is a view, not the record',
      body: '<code>docs/design/</code> is the system of record. This site is a separate deliverable that presents the design interactively. When they disagree, the record is right and the site is fixed to match.' },

    { n: 28, s: A, t: 'Python first', body: 'The first client is Python (3.14+): async first, with a sync shell for DB-API later. It lives in <code>clients/python/</code>.',
      why: 'It serves the expected users directly, and its generators and in-memory TLS fit the core/shell split.' },
    { n: 24, s: A, t: 'A sans-I/O core with a thin shell', link: ['client', '2-core-and-shells'],
      body: 'The connection manager is one package of two files: <code>core.py</code> holds all protocol logic and never does I/O; <code>shell.py</code> (asyncio) owns the socket, the timer and the tasks. Procedures yield actions (send, read, receive); the shell performs them.' },
    { n: 31, s: A, t: 'MARS is part of the connection manager’s core',
      body: 'MARS framing, sessions and flow control live in <code>connection/core.py</code>. Login happens before MARS framing starts; each serial channel is then one MARS session.',
      why: 'MARS is how the connection manager provides serial channels (D-18), so it is core to the design.' },
    { n: 33, s: A, t: 'One primitive: an exchange',
      body: 'Every operation an application performs is one exchange in the conversation: the client sends one request, then reads the server’s complete response. <code>channel.exchange(request) → response</code> is the single primitive, and it is public, documented as the low-level interface. Conveniences (query, fetch, call, prepare, describe, …; D-37) only choose a request and how to read its response.',
      why: 'One abstraction for the same kind of thing. A new capability is a new kind of request or a new way of reading a response, never a new mechanism. The channel rules, cancel and observability live in one place. <b>Constraint:</b> <code>exchange</code> and the response reader never branch on the kind of operation; differences live in the request definitions and the conveniences. A branch on the operation in either place is a design problem to report, not to work around.' },
    { n: 34, s: A, t: 'Responses stream, forward-only, read through explicit choices', link: ['client', '4-exchanges-and-responses'],
      body: '<code>exchange</code> always returns the open response, read incrementally and forward-only. Iterating it yields result sets; iterating a result set yields rows; moving to the next result set discards the current one’s unread rows. <code>fetch()</code> reads to the end and returns a <code>FetchedResponse</code>: a specialization of the response, backed by memory, channel freed, adding re-reading and indexing. <code>finish()</code> reads to the end, skipping rows. <b>Stopping:</b> <code>close()</code>, by the owner, cancels a response that hasn’t ended and reads to the acknowledgement; <code>cancel()</code> may be called from any task (D-23): it sends Attention and returns at once, and the owner’s next read raises <code>Cancelled</code>. <code>returns()</code> is awaitable and takes <code>unread: Unread</code> (<code>REFUSE</code> by default, <code>KEEP</code>, <code>DISCARD</code>), because the returns come at the end; it gives one entry per call the server completed. Completions and messages are read as they pass (D-42). An open response holds its serial channel; errors are raised at the end by whichever call reaches it, carrying the whole record (D-42); a response dropped while open raises a <code>ResourceWarning</code>. <i>Revised the same day.</i>',
      why: 'Streaming is the one mechanism; reading everything is a way of using it. One way to read results, live or fetched. Unread items are never kept or discarded silently. No mode flags on <code>exchange</code> (D-33).' },
    { n: 35, s: A, t: 'Never hide reality; expose it gracefully',
      body: 'The driver never hides what the protocol and the server actually do. It shows them in a form that is easy to read and use, and stays elegant throughout. Every design choice is checked against two questions: <i>what reality could this hide?</i> and <i>how can it be shown plainly?</i>',
      why: 'Already applied: MARS shown as taking turns, not parallelism (D-18); misuse that fails every time, not by timing (D-21, D-22); unread items never kept or discarded silently, and errors that arrive with the partial results (D-34); a response shown as the record of what the server did, with no invented structure (D-42); every value read going back exactly, never rounded or replaced (D-48); observability that shows every byte (D-12); observed server behavior that MS-TDS doesn’t state, written down.' },
    { n: 36, s: A, t: 'Connections are lent whole; requests happen only on a serial channel', link: ['client', '3-connections-and-serial-channels'],
      body: 'A pool lends whole connections, exclusively, and never reaches inside one: serial channels are opened from the borrowed connection. Giving a connection back resets its session; one given back with a request still in progress is closed, never lent again. <b>Neither the pool nor the connection makes requests:</b> requests are made only on a serial channel. Convenience methods may come later if experience shows they’re needed; whether SQL and procedure helpers belong on the connection is an open question.',
      why: 'A connection is a session. Lending MARS channels of a busy connection to unrelated callers would silently share their transactions and settings (D-35). A pool that runs SQL is a surprise, because a pool deals in connections; a connection that runs SQL hides the serial channel, the abstraction MARS adds. <b>Rejected:</b> lending channels; lending “channels” that are really exclusive connections; shortcut request methods on the pool and the connection.' },
    { n: 37, s: A, t: 'The serial channel’s conveniences (a layer around the driver, D-39; built in M16)', link: ['client', '4-exchanges-and-responses'],
      body: '<code>exchange</code>, <code>query</code>, <code>fetch</code>, <code>fetch_value</code>, <code>call</code>, <code>prepare</code>, <code>describe</code>, <code>transaction</code>. Cancel is not among them: it is the response’s own <code>cancel()</code> (D-34). Shortcuts check their shape: <code>fetch_value</code> refuses anything but exactly one row and one column; <code>FetchedResponse.rows</code> exists only for exactly one result set. No aliases.',
      why: 'Each convenience is one exchange plus a way of reading its response (D-33, D-34); the shape checks never quietly pick “the first one” (D-35).' },
    { n: 39, s: A, t: 'The driver represents SQL Server as TDS exposes it; application abstractions wrap it', link: ['client', '0-the-driver-and-the-layers-around-it'],
      body: 'The driver represents SQL Server’s functionality as TDS exposes it, as clearly and simply as possible: connections and the pool, serial channels, exchanges and responses, the protocol’s own requests (<code>Batch</code>, and <code>Call</code> for any procedure by name or built-in number, with <b>explicitly typed</b> parameters), cancel, and session state. Application-level abstractions (parameterized statements, prepared statements, server cursors, type inference, conveniences, DB-API) live in layers around it, using only its public surface. Type inference is outside the driver.',
      why: 'The driver teaches TDS and nothing else; each outer layer teaches its own conventions and is the driver’s first real client. Composition adds no round trips.' },
    { n: 40, s: A, t: 'Call: an RPC as TDS defines it',
      body: '<code>Call(target, *params, options=…)</code>: the target is a procedure name or a <code>tds.Builtin</code>; <code>Param(name, type, value, output=False)</code> mirrors the wire, in an ordered list; <code>output=True</code> passes it by reference, TDS’s only output mechanism, sending the value as given (the procedure sees it). <code>tds.types</code> is one vocabulary for parameters and columns; values are checked against their declared type before sending, and nothing is inferred; <code>varchar</code> uses the session’s collation unless given one. <code>tds.DEFAULT</code> means the procedure’s default. <code>tds.Calls(…)</code> sends several calls in one request, and <code>returns()</code> gives one entry per call the server completed (D-42); an error that ends the batch leaves later calls without entries. Outputs are matched by ordinal, the parameter’s position from 0, because the server moves large outputs to the end. <code>CallOptions</code>: <code>RECOMPILE</code>, <code>NO_METADATA</code> (must supply earlier columns), <code>REUSE_METADATA</code>. No single-call shortcuts. <i>Revised the same day.</i>',
      why: 'Exactly what TDS offers, no more and no less (D-39). Keyword arguments, inferred types and “the only call’s outputs” belong to outer layers. <b>Rejected:</b> <code>Direction.IN</code> / <code>OUT</code> / <code>IN_OUT</code>: the wire has one by-reference flag and SQL Server output parameters are always input too, so OUT versus IN_OUT only decides whether a library sends NULL for the application, a convention for an outer layer. Also rejected: the NO-EXEC separator, which skips the preceding call in a multi-call request. It exists to withdraw a call already being sent; the driver sends <code>Calls</code> only once fully built and checked, and a failed streamed request is abandoned whole (D-41), so nothing runs partially.' },
    { n: 41, s: A, t: 'Streamed requests, for bulk load and large values', link: ['client', '4-exchanges-and-responses'],
      body: 'Requests may be sent as a stream where TDS supports it and it matters: <b>bulk load</b> (a stream of rows) and <b>large values</b> (<code>…(max)</code>, <code>xml</code>, sent in chunks of unknown total length). <code>exchange</code> stays the one primitive; a streamed request’s values are sources (async iterators). If a source fails partway, the whole request is abandoned with the <i>ignore</i> flag: the server runs nothing and says so, the driver reads that answer, then raises the source’s error. <b>Sources may be given to any parameter of a <code>Call</code>, in <code>Calls</code> too</b> (amended 2026-10-16): abandoning drops the whole message, every call in it. A whole large value is sent with its length known; a source as it produces. Each chunk is checked as it is encoded (D-48). <b>One way to abandon a request mid-send</b> (agreed 2026-10-16): a source fails, a chunk is refused, or the task is canceled while sending; the next packet carries <i>ignore</i> + <i>last</i>, the driver reads the server’s answer, then raises the original error or <code>CancelledError</code>. <b>Status:</b> large values in M4; bulk load later.',
      why: 'Streaming makes bulk load practical and large values affordable; all-or-nothing abandonment makes a failure unambiguous.' },
    { n: 42, s: A, t: 'A response is the record of what the server did; its structure is read through token rules', link: ['client', '4-exchanges-and-responses'],
      body: `<b>The record:</b> one ordered sequence of items, one per server token (rows belong to their result set): <code>ResultSet</code> (COLMETADATA, ROW / NBCROW, ORDER; <i>added in M11:</i> TABNAME, COLINFO, DATACLASSIFICATION, ALTMETADATA, ALTROW), <code>Completion</code> (DONE, DONEINPROC, DONEPROC), <code>Message</code> · <code>Error</code> (INFO · ERROR), <code>ReturnStatus</code> · <code>OutputValue</code> (RETURNSTATUS · RETURNVALUE), <code>Announcement</code> (ENVCHANGE), <code>SessionState</code> (SESSIONSTATE, <i>added in M11</i>). <code>response.sequence</code> holds it as far as read; a <code>FetchedResponse</code> and a <code>ServerError</code> hold all of it. <b>Views, each one token rule</b>, never what was requested (D-33): result sets (COLMETADATA opens, the next completion closes); <code>response.completions</code> as <code>Completion(kind, rows, status, statement)</code>, with <code>rows</code> <code>None</code> when the count isn’t valid and the statement code raw; <code>response.messages</code>, <code>response.errors</code>; <code>returns()</code>, one <code>Return</code> per DONEPROC with <code>status</code> (<code>None</code> if the call never reached <code>RETURN</code>), outputs by ordinal and name, a function’s result, and <code>failed</code>. <b>Rows are plain tuples</b>; names and types are on <code>result_set.columns</code>. Rows that streamed past are counted, not kept. Errors carry the whole record, identical at every observability level. See ${L('ref/response', 'Request Response')}.`,
      why: `The token stream is flat and its nesting irregular: batches mix statements with <code>EXEC</code>s, nested procedures flatten into their caller, a call can fail before it starts, and a request can stop partway through its calls. Showing the record as it is, with views that are each one rule, keeps every fact visible and leaves interpretation to outer layers, which know what they sent (${L('client', 'The Client §5', '5-how-outer-layers-read-a-response')}). <b>Rejected:</b> a tree (response → call → statement → result set), which would invent structure; turning “no count” into 0; access by column name in the driver, since names may be empty or repeated.` },
    { n: 43, s: A, t: 'The type vocabulary covers every type TDS 7.4 defines', link: ['build', '3-the-components'],
      body: 'All of them, built in milestones (D-46): the short types (numbers, dates and times, text, binary, <code>uniqueidentifier</code>); large values (<code>(max)</code> types, <code>xml</code>, <code>text</code> / <code>ntext</code> / <code>image</code>); <code>sql_variant</code>, <code>json</code> and <code>vector</code>, CLR types, and table-valued parameters. <b><code>json</code> and <code>vector</code> arrive as their real types:</b> without login features the server sends both as nvarchar, so the login asks for JSONSUPPORT and VECTORSUPPORT (D-8). <b>CLR types</b> are bytes plus the type’s full name; shapes and paths belong to an outer layer (D-39). <b>The legacy codes</b> (<code>37 3F 2F 27 2D 25</code>) are recognized and refused with an error that names them. The Python value for each type follows D-48: a Python type only where it holds every value exactly, a driver type otherwise.',
      why: 'An application must handle whatever types its schema uses. A vocabulary with gaps fails on real databases, and a down-converted type hides reality (D-35).' },
    { n: 44, s: A, t: 'Collations come from one definition file generated from the server', link: ['build', '3-the-components'],
      body: '<code>tds/collations.py</code> maps locale id → code page and sort id → code page, and records the UTF-8 flag. <b>It records where SQL Server reads or writes each code page differently from Python’s codec</b>, measured on the live server (17.0.5015) for every single byte and every double-byte pair: bytes Python refuses that the server reads as C1 controls or private-use characters (5 in cp1252, 23 in cp1255, 31 in cp874); whole user-defined areas in the double-byte code pages (2,151 sequences in cp936, 6,219 in cp950); 249 cp950 sequences read as other characters; and cp932’s duplicate encodings. <b>A sequence reads as the server’s character only when the server writes that character back as the same bytes;</b> any other is carried as escapes, so every value goes back unchanged (D-48). <b>UTF-8:</b> invalid bytes the server stores, it sends with U+FFFD in their place (without the UTF-8 login feature, D-8). The file is loaded whole with the module, generated from the server (<code>sys.fn_helpcollations()</code>, <code>COLLATIONPROPERTY</code>) by a script kept in the repo, and records the server version it came from; MS-TDS contains no such table. A collation missing from the file fails clearly, naming its locale id, sort id and bytes; the driver never sends its own lookup query (D-36). A <code>varchar</code> value is decoded with its column’s own collation; a parameter is encoded with the session’s or one given explicitly (D-40).',
      why: 'The server’s 5,540 collations reduce to 81 locale ids, 76 sort ids and 17 code pages. Loading the whole table costs microseconds, so a lazy-loading tier would add a second code path and save nothing. The server, not Python, defines what a byte means.' },
    { n: 45, s: A, t: 'Where requests, types and responses live', link: ['build', '2-where-the-code-lives'],
      body: '<code>requests.py</code> replaces <code>batch.py</code> (the shared headers, <code>Batch</code>, <code>Call</code> / <code>Calls</code> / <code>Param</code> / <code>Builtin</code> / <code>CallOptions</code> / <code>DEFAULT</code>). <code>types.py</code> replaces <code>datatypes.py</code>, matching the public <code>tds.types</code>. <code>response.py</code> is new: the record, its views and the reading state machine, with no I/O; the live <code>Response</code> is a thin async layer in <code>shell.py</code>. <code>tokens.py</code> adds RETURNVALUE, RETURNSTATUS, NBCROW and ORDER. Each surface is mirrored by a reference page: Requests, Data Types, Request Response.',
      why: 'Strongly related concepts stay together, and each teaching surface mirrors one reference page (D-27).' },
    { n: 46, s: A, t: 'Milestones M1–M8', link: ['build', '4-milestones'],
      body: 'M1 requests and the response record · M2 every short type · M3 calls · M4 large values in both directions · M5 <code>sql_variant</code> · M6 <code>json</code> and <code>vector</code> · M7 CLR types · M8 table-valued parameters. Each uses only what earlier ones built, ends with its tests passing against the live server, and comes with its reference pages. Its checks are in Done When.',
      why: 'Everything is included, and nothing depends on something not yet built: <code>sql_variant</code> needs the base types; <code>json</code> needs large values and a login feature.' },
    { n: 48, s: A, t: 'Every value round-trips exactly', link: ['build', '3-the-components'],
      body: `<b>The rule:</b> select → insert → select compares equal, for every type, on the server and in Python, tested with values the server generates. <b>A value goes back with its column’s type</b>, the same object as a parameter’s, carrying collation, precision, scale and length (D-40). <b>A Python type is used only where it holds every value of the SQL type exactly, at every scale; otherwise the value is a driver type:</b> <code>int</code>, <code>bool</code>, <code>Decimal</code> (encoded from its digits, never through <code>float</code> or decimal arithmetic), <code>float</code>, <code>datetime.date</code>, <code>datetime.datetime</code> for <code>smalldatetime</code>, <code>str</code> (varchar decoded with the server’s byte table; nvarchar keeping unpaired surrogates), <code>bytes</code>, <code>uuid.UUID</code>; driver types for <code>time</code>, <code>datetime2</code>, <code>datetimeoffset</code> (100 ns ticks, plus the offset) and <code>datetime</code> (1/300-second ticks), for <code>vector</code>, and for <code>sql_variant</code> (value with its base type); CLR types as bytes and type name; <code>xml</code> and <code>json</code> as <code>str</code>, verified from their first normalized form. Driver time types convert to Python’s exactly, or refuse unless rounding is asked for. <b>Refuse rather than round, in both directions:</b> a value that doesn’t fit its declared type exactly is refused before sending. <b>Where the server sets the limit</b> (observed, M3): SQL Server types a declared <code>varchar</code> parameter in the database’s default collation and converts into it, so a <code>varchar</code> value in another collation goes back exactly through a parameter declared <code>nvarchar</code>, except the sequences the server itself writes back differently; and it sends invalid UTF-8 it stores with U+FFFD in its place (D-44). The driver shows both; it can’t undo them.`,
      why: 'A driver that rounds, truncates or replaces silently hides reality (D-35), and code that reads a value and looks for it again would fail in ways nobody can see. Exactness, not convenience, decides each type.' },
    { n: 9, s: A, t: 'Login flags are named options of connect; the ODBC flag is on unless turned off (revised the same day)', link: ['ref/login7', 'flags'],
      body: `<b>Login flags are passed to <code>connect</code> by name,</b> named as MS-TDS names them. The first is <code>odbc</code>: LOGIN7’s ODBC flag (fODBC, bit 1 of option flags 2). <b>The ODBC flag is on by default, and stays explicit:</b> a named parameter that <code>odbc=False</code> turns off, shown on the login line in observability, because the server never announces it. <i>Revised:</i> it was off by default until M4’s design showed the cost: when it is off, TEXTSIZE is 4,096 bytes, so every large value is silently cut, which breaks D-48. <b>The driver never changes a session with SET statements of its own.</b> <b>What it gives</b> (measured): on, the default, means ANSI_NULLS, ANSI_PADDING, ANSI_WARNINGS, CONCAT_NULL_YIELDS_NULL and QUOTED_IDENTIFIER on and TEXTSIZE unlimited; off means those options off and TEXTSIZE 4,096 bytes; ARITHABORT is off either way. It is what ODBC, .NET and JDBC clients send. With <code>odbc=False</code>: writes to tables with filtered indexes, indexed views or indexes on computed columns fail (error 1934); overflow and division by zero give NULL; <code>NULL + N’x’</code> is <code>N’x’</code>; <code>char(n) NULL</code> columns created in the session hold values unpadded; large values arrive cut to 4,096 bytes. <b>The other identity flags</b> (<i>agreed 2026-10-16</i>): <code>read_only_intent=False</code> tells the server the connection only reads, so an availability group can route it to a readable secondary; it is a routing hint, not enforcement (a standalone server accepts it and still allows writes), documented so, and the command line prints a brief note whenever <code>--read-only-intent</code> is used. <code>language=</code> sets the session’s language (default: the login’s own, or else the server’s <code>default language</code>); an unknown one fails the login (4019). Identity is sent truthfully: the real process ID (<code>host_process_id</code>), <code>host_name=</code> (default <code>socket.gethostname()</code>) and <code>app_name=</code> (D-8). <b>The database must succeed, always:</b> without <code>database=</code> the server uses the login’s default and announces it (<code>connection.session.database</code>); if it can’t be opened the login fails, with no fallback to <code>master</code>, and the error explains why (dropped, offline, or no user for the login) and what to do (name one, or <code>ALTER LOGIN … WITH DEFAULT_DATABASE</code>). <b>Left out:</b> the OLE DB flag, binary XML and unknown collation handling (ignored by SQL Server), user type, user instances and attaching a database file; changing an expired password stays with M17.`,
      why: 'The default gives the session most users expect, and keeps large values whole. Turning it off takes one named parameter, and both settings are documented (D-35).' },
    { n: 47, s: A, t: 'Large values in responses: read whole, or streamed value by value', link: ['client', 'large-values'],
      body: `<b>Two ways to read a result set, both forward-only:</b> <code>async for row in result_set</code> gives tuples, with every value whole, large ones included (the memory is the application’s choice); <code>result_set.streamed()</code> gives rows read value by value, in column order, each large value (<code>(max)</code> types, <code>xml</code>, <code>text</code>, <code>ntext</code>, <code>image</code>) arriving as a <code>ValueStream</code>. <b>A <code>ValueStream</code></b> is an async iterator of <code>bytes</code> (binary) or <code>str</code> (text, <code>xml</code>), readable while its row is current and only once; moving to the next value discards what is unread; text is decoded as it arrives, with the column’s collation, never split inside a character. <code>fetch()</code> and <code>Unread.KEEP</code> keep large values whole. <b><code>(max)</code></b> is spelled <code>types.varbinary(types.MAX)</code>, <code>types.nvarchar(types.MAX)</code>, <code>types.varchar(types.MAX, collation=…)</code>. <b>Observability never holds a large value whole:</b> chunk count, total length and first bytes.`,
      why: 'On the wire a row is its values in column order, and a large value is chunks of unknown total length: a 1 GB value must be read, or skipped, before the next column exists. Tuples keep the common case simple; <code>streamed()</code> shows that reality to the code that needs it, with no mode flag on <code>exchange</code> (D-33). <b>Rejected:</b> stream objects inside every tuple; declaring per column which values stream.' },
    { n: 49, s: A, t: 'A table-valued parameter is a table type and its rows', link: ['ref/types', 'shape'],
      body: `<b>The type is written with its columns’ types, in order, and no names:</b> <code>types.table("shop.price_change", types.int, types.decimal(10, 2))</code>; TDS sends no column names. <b>A column the server fills</b> (identity, computed, or with a default) is marked <code>types.default(type)</code>: it is described, with MS-TDS’s default flag, and rows omit its values, for example <code>types.table("shop.order_line", types.default(types.int), types.int, types.int, types.default(types.int))</code> with rows <code>[(7, 2), (9, 1)]</code>. <b>The rows are any iterable of tuples, or an async source of tuples,</b> sent as they arrive; a source that fails partway abandons the request as a large value’s source does (D-41). <code>DEFAULT</code> sends TDS’s “no table” marker. <i>Amended by D-53:</i> <code>None</code> sends it without the default bit, and the server refuses it; the table type checks only what its encoding needs. <b>The optional wire features are included:</b> a sort and uniqueness hint (TVP_ORDER_UNIQUE) and a different column send order (TVP_COLUMN_ORDERING), as options on the table type.`,
      why: 'Each part matches what TDS sends. Names that never reach the server would suggest they matter; a per-row placeholder would hide that the flag is per column. The ordering features are wire features, not conveniences, and column ordering is how a large value is sent last so it can be streamed.' },
    { n: 50, s: A, t: 'Bulk load is two requests, and the application writes both', link: ['ref/requests', 'shape'],
      body: `<b><code>tds.BulkInsert(sql)</code></b> is the application’s own <code>INSERT BULK …</code> statement, sent as a SQL batch; a request type of its own, so the serial channel knows a bulk load is open without reading the SQL. <b><code>tds.BulkRows(columns, rows)</code></b> is the bulk data message: its header of columns (COLMETADATA), then the rows, then DONE. Rows are an iterable or a source of tuples (D-41); large values go in chunks with their length unknown, the form MS-TDS defines and the server accepts. <b>The two must describe the same columns exactly</b> (columns, order, types, nullability). The documentation recommends taking the columns from <code>SELECT TOP 0 * FROM table</code> and writing the statement from the same columns. <b>The server checks the agreement,</b> and its refusals leave the connection usable; the driver refuses only what it can’t encode (D-48). <i>Amended 2026-10-16:</i> the driver was to check, before sending, for empty names and for types that bulk data refuses. A general rule replaced this: little semantic checking before sending; let the server say what’s wrong. <b>The channel keeps the pair together:</b> after a successful <code>BulkInsert</code> the next request must be <code>BulkRows</code>, and <code>BulkRows</code> is refused at any other time, because bulk data out of turn makes the server close the connection. <b>The docstrings state this contract</b> for the convenience layer, which will provide a helper that writes the statement and its options from the columns (D-39).`,
      why: 'Each request is exactly what TDS sends, and the driver writes no SQL; the one unrecoverable failure, bulk data out of turn, is prevented by the channel. <b>Rejected:</b> the driver writing <code>INSERT BULK</code> (the one place it would write SQL, hiding the statement sent); one <code>BulkLoad</code> request making both exchanges (breaks D-33); <code>INSERT BULK</code> options named in the driver.' },
    { n: 51, s: A, t: 'Transaction-manager requests: one request class each, exposed as the server provides them', link: ['ref/requests', 'shape'],
      body: `<b>One class per MS-TDS request, with plain names, in <code>tds.transactions</code>:</b> <code>Begin(isolation=None, name="")</code>, <code>Commit(name="", begin=None)</code>, <code>Rollback(name="", begin=None)</code> (the name may be a savepoint’s), <code>Save(name)</code>, <code>Promote()</code>, <code>Propagate(cookie)</code>, <code>CoordinatorAddress()</code>. <code>begin=Begin(…)</code> is MS-TDS’s <i>begin another</i> flag; <code>Isolation</code> is an enum, and <code>None</code> leaves it unchanged. <b>The results are in the response, as the server provides them:</b> the transaction state in the session and the response’s announcements, promote’s token in its announcement, the coordinator’s address in the response’s one row, each documented with the request that produces it. <b>Little semantic checking before sending:</b> the server says what’s wrong, and the documentation says what follows (a refused savepoint name rolls back the open transaction). Only what can’t be encoded is refused: a name longer than its u8 byte count allows. <b><code>Propagate</code> is sent as MS-TDS defines it, and marked untested:</b> it needs a cookie from a coordinator, so only its refusal is tested. The enlist, defect and transaction-ended announcements are marked unobserved.`,
      why: 'Each request is one exchange (D-33), and the session already follows the announcements, so these are requests and nothing more. Checks that duplicate the server’s would be a second, weaker statement of its rules.' },
    { n: 52, s: A, t: 'Milestones M9 and M10', link: ['build', '4-milestones'],
      body: `The second sequence begins with <b>M9 · Bulk load</b> (D-50) and <b>M10 · Transaction manager</b> (D-51), checked as ${L('done-when', 'Done When')} lists. For both, every behavior documented on Requests, Request Response and Token Stream, deviations from MS-TDS included, has a live test.` },
    { n: 53, s: A, t: 'The server judges; errors are literate', link: ['client', 'reading-a-response'],
      body: `<b>Little semantic checking before sending.</b> The driver refuses only what it can’t encode, or couldn’t encode exactly (D-48): a value out of range, a name too long for its length field, a row whose values can’t be placed. Everything else goes to the server, which says what’s wrong; the documentation says what a refusal causes, such as a rolled-back transaction. <b>Errors are literate, carrying all the applicable information:</b> a <code>ServerError</code> shows every error in SQL Server’s own form (<code>Msg</code>, <code>Level</code>, <code>State</code>, <code>Procedure</code>, <code>Line</code>, the server, the text), then what its level means as Microsoft documents it, with the messages that came with it, which request was refused, which call for several calls, and what the server did next: its announcements, and whether it continued. A refused login shows the server’s report the same way; the driver’s own errors say what was refused, why, and what to do instead; a refused value says where it was, each layer adding its place (<code>the call to shop.update_prices › parameter @changes (shop.pc) › row 2 › column 2 (decimal(10, 2)): …</code>), whether refused before sending, while encoding, or while a source was producing it. <b>Applied to what is built:</b> D-50’s checks before sending were dropped; D-49’s table type checks only what its encoding needs; <code>None</code> for a table, an output table, a column count the type doesn’t have, a nested table and a hint the server rejects all reach the server, and each refusal is tested live.`,
      why: 'The server is the authority on its own rules, and a second, weaker copy of them in the driver would hide what the server says. When it refuses, its full report is what the application needs.' },
    { n: 54, s: A, t: 'The other logins come last, tested on transient Azure infrastructure', link: ['ref/conversations', 'what-each-way-of-logging-in-needs--built-d-54-d-55'],
      body: `<b>Deferred until the rest of the driver is built:</b> Windows logins (Kerberos, NTLM), federated logins (Entra ID tokens, given in advance or fetched during login), and the SQL login variants (changing an expired password, contained-database users). <i>Built and tested in M17, 2026-10-17 (${D(55)}, ${D(62)}).</i> <b>They are documented now:</b> what each needs on the server and the client, and how each will be tested. <b>They will be tested on transient infrastructure in Azure,</b> created for the purpose and deleted afterward: a Windows Server domain controller and SQL Server for Kerberos and NTLM, and an Azure SQL Database with an Entra ID tenant for federated logins.`,
      why: 'None of them can be tested against the local container alone. SQL Server on Linux accepts only Kerberos for integrated logins, and needs a domain; federated logins need Entra ID.' },
    { n: 56, s: A, t: 'Milestones M11–M18', link: ['build', '4-milestones'],
      body: `The rest of the second sequence, in this order: M11, every token the server can send; M12, Slice 1’s failures, tested; M13, TDS 8.0 and the observability levels; M14, connection and login options (session recovery, the remaining login features and flags, the DAC, routing and a Browser client); M15, Always Encrypted; M16, the convenience layer and the synchronous shell (DB-API removed 2026-10-16: it would be a separate project, depending on this one), built after M17 and M18 (D-62); M17, the other logins, on Azure; M18, the Azure-only login features, on the same infrastructure (<i>added 2026-10-16</i>, D-8). Each is checked as ${L('done-when', 'Done When')} lists, and names the decisions it needs first.`,
      why: 'A token the driver can’t read ends the connection on ordinary SQL, so it comes first. Then quick tests that complete Slice 1. Then the core behaviors testable locally, then the layers around the driver. What needs Azure comes last.' },
    { n: 10, s: A, t: 'Encryption and certificates', link: ['ref/connect', 'rules'],
      body: `<b>TDS 8.0 is chosen explicitly:</b> <code>connect(…, tds_version="8.0")</code>, or <code>strict=True</code>, which says the same and matches Microsoft’s drivers (<code>Encrypt=Strict</code>); the default is <code>"7.4"</code>. <b>There is no automatic fallback:</b> if 8.0 fails, the error says why and what the options are, such as <code>tds_version="7.4"</code>. <b>Under 7.4, the whole connection is encrypted, or the connection fails</b> with an explanation; there is no unencrypted mode. <b>Certificate checking uses Python’s standard,</b> an <code>ssl.SSLContext</code> passed as <code>ssl_context</code>. The default verifies against the system’s trusted authorities and the host name; anything else is set through the context (a specific authority, a pinned certificate, a minimum TLS version, or no verification at all), and a certificate that names another host is checked against <code>server_hostname=</code>, as <code>asyncio.open_connection</code> takes it. Each is documented with an example. <code>trust_server_certificate</code> is removed. Under 8.0, a context that doesn’t verify is refused, as Microsoft’s drivers refuse <code>TrustServerCertificate</code> in strict mode. <b>The test container presents a certificate from a test authority,</b> set up by a script kept in the repo and documented so it can be reproduced; tests trust that authority, not every certificate.`,
      why: 'The choice of protocol version changes what is protected, so it is the application’s to make, and visible. Python’s <code>ssl</code> module already expresses everything about certificates; a second vocabulary would hide it.' },
    { n: 12, s: A, t: 'Observability levels', link: ['client', '6-what-the-running-client-shows'],
      body: `<b>Three levels:</b> off (no inspection trees and no event text, the cheapest), outline (one line per step, message and change), full (every message opened to its fields and bytes). <b>Set per connection at <code>connect</code>, and changeable between exchanges</b> on a live connection. <b>Events go to the <code>observe</code> callable;</b> the printer is one observer, and adapters to <code>logging</code> or OpenTelemetry live outside the core (D-39). <b>Full shows each field’s first bytes, with every byte reachable in the tree;</b> large values are summarized (D-47), and each structure is labeled with the reference page that explains it. <b>Captures and replay:</b> a capture holds every message’s bytes in both directions, after TLS, with timestamps, as JSON lines; the password is removed by default, because LOGIN7’s scrambling is reversible; query text and data stay, and the documentation warns that captures hold data; replay decodes a capture into the identical view. <b>The password stays hidden at full level</b> unless explicitly revealed for that session. <b>Timing</b> (<i>agreed 2026-10-16</i>): each event has a time on a monotonic clock. Each connect step shows its time since connecting began (<code>at 24 ms</code>); each response, the time from sending to its first packet and to its end (<code>first packet 12 ms · done 40 ms</code>). Durations are shown at the end of the line, separate from its text. A capture records them, so replay shows the same values; a capture’s first line records the wall-clock start, to align it with server logs. <code>response.timing</code> gives applications the same (sent, first packet, ended), collected at every level: three clock reads per exchange.`,
      why: 'The application chooses how much the client collects, and can change that choice on a live connection. The view is generated from the definitions, so a capture replays to exactly what was seen.' },
    { n: 8, s: A, t: 'Features requested at login: a list, with a documented default', link: ['ref/login7', 'shape'],
      body: `<b><code>connect(features=…)</code> takes the list of features the login asks for;</b> the default is <code>tds.DEFAULT_FEATURES</code>. Features are named as MS-TDS names them (<code>tds.Feature.UTF8_SUPPORT</code>, …), and the driver chooses the version it implements for each. A feature the driver can’t read yet is refused with an error that says why and when (column encryption until M15, federated authentication until M17). The command line has an on/off switch for each, with its default shown in <code>--help</code>; <code>connection.features</code> shows what the server accepted. <b>The default list:</b> JSON support (1) and vector support (2), so <code>json</code> and <code>vector</code> arrive as their real types; <b>UTF-8 support</b>, without which SQL Server sends invalid stored UTF-8 bytes with U+FFFD in their place, and with which they arrive as stored and go back exactly (D-48); <b>data classification, version 2</b>, so a classified result set carries its labels as <code>result_set.classification</code>, with the negotiated version passed to the reader; <b>session recovery</b>, once M14 builds it. <b>Not requested:</b> column encryption until M15 (it changes every result’s column descriptions); the Azure-only features until M18; the user-agent feature (the server ignores it, and SQL Server already identifies the driver as <code>client_interface_name</code> “tds”). <b><code>connect(app_name=…)</code></b> sets the session’s <code>program_name</code> (default “tds (python)”). <b>Every option is documented in one place:</b> the Options section of ${L('ref/connect', 'Connect')}, mirrored by <code>tds --help</code>. <b>Reading data classification:</b> <code>rs.classification</code> is <code>None</code> when no column is classified; otherwise <code>rs.classification.columns</code> gives each column’s sensitivities, each with a <code>label</code> and an <code>information_type</code> (name, id) and a <code>rank</code> (−1 not defined · 0 none · 10 low · 20 medium · 30 high · 40 critical; from version 2), and <code>rs.classification.rank</code> the result set’s own. The labels are the database’s; masking, warning or logging belongs to the application (D-39).`,
      why: 'Each feature changes what the server sends, so the list is the application’s, with a default that gives exact values and everything the server knows (D-35, D-48). A feature the reader can’t handle would break ordinary queries, so it can’t be asked for.' },
    { n: 11, s: A, t: 'Routing: followed once', link: ['ref/connect', 'rules'],
      body: `<b>A routing announcement in the login reply is followed, once, by default:</b> the driver closes the connection, connects to the named server and port with the same options, and logs in again; the steps show the hop, and <code>connection.routed_from</code> records where it was sent from. <code>follow_routing=False</code> raises <code>Routed(server, port)</code> instead. <b>Only one redirect:</b> a second fails with an error naming the whole chain. <b>Credentials go to the new server only after its certificate is verified for the new name</b> (D-10); a <code>server_hostname</code> given by the application applies to the first server only. <b>One connection timer covers both connections.</b> <b>Enhanced routing</b> (ENVCHANGE 21, with a database) isn’t followed yet: in M18 the test server acknowledged the feature with 0, so none arrived. <b>A routed login names the routed server and port,</b> <code>server,port</code>, in LOGIN7: Azure SQL’s nodes refuse the name the application asked for (observed 2026-10-17; SqlClient does the same). <b>Tested</b> locally with a fake router presenting the test certificate; live on Azure SQL Database (connection policy Redirect) in M17, under TDS 7.4 and 8.0.`,
      why: 'Azure SQL Database routes every connection made from inside Azure, and availability groups route read-only intent. Following once is what those designs expect, and what Microsoft’s drivers do; more than once would risk a loop.' },
    { n: 57, s: A, t: 'Session recovery: automatic, and explicit', link: ['ref/connect', 'session-recovery'],
      body: `<b>The login asks for session recovery by default</b> (it joins <code>tds.DEFAULT_FEATURES</code>, ${D(8)}). The server acknowledges it with the session’s initial state, and SESSIONSTATE tokens report each change after that. <b>Automatic:</b> when an exchange is about to start and the connection is found broken while idle, the driver recovers it once, then sends. <b>Explicit:</b> <code>await connection.recover()</code> does the same on demand. <b>Recovery opens a new connection</b> with the same options and logs in carrying the session’s state: its initial state and its current one (database, language, collation, and the session states); the server rebuilds the session from them. <b>A request in progress when the connection broke is never resent:</b> nobody can know whether it ran; its error says so, and the application decides. <b>Visible:</b> the steps show it (<code>recover</code>), and <code>connection.recoveries</code> counts recoveries. A server that refuses, or a session it marked not recoverable, gives a literate error naming why. <b>Continuing permissions, agreed after experiment:</b> retain logical channel owners and connection/channel close permissions, allocate fresh physical MARS wire ids and retire old exchange authority. Rust epoch guards and Python’s pinned core/transport prevent late old reads, cancels or abandonment from affecting replacements. Retained data remain inspectable, application-closed lifetimes stay closed, and interrupted SQL is never replayed or assumed rolled back. Each physical connection owns a separate recording. See the ${L('recovery-experiment', 'experiment and results')}.`,
      why: 'Applications using Microsoft’s drivers expect idle connections to survive a brief network failure or a failover; the rule for requests in progress ensures that recovery never runs a request twice.' },
    { n: 58, s: A, t: 'The mirroring partner is shown, not acted on', link: ['ref/login-response', 'shape'],
      body: `The login reply’s mirroring partner announcement (database mirroring) is kept as <code>connection.session.mirroring_partner</code>. The driver never connects to it on its own: trying the partner is the choice of the application, or of a layer around the driver (${D(39)}). Mirroring is deprecated, and SQL Server on Linux doesn’t have it, so it’s tested live on Windows (M17).`,
      why: 'The driver shows what SQL Server says; deciding where to connect next is an application’s policy.' },
    { n: 59, s: A, t: 'The Browser client: ASCII unless told, a timeout in milliseconds, and separate from connect', link: ['ref/browser', 'rules'],
      body: `<b>Text is ASCII unless <code>encoding=</code> names the code page</b> the client and server share. MC-SQLR never says which it is, so the driver doesn’t guess: a name ASCII can’t hold is refused before sending, and a reply ASCII can’t read is reported with the byte that failed. The Browser page says how to find a server’s code page and pass it. <b>Every call waits <code>timeout_ms</code> for its reply,</b> 1000 ms by default (MC-SQLR suggests 1 second); a broadcast gathers replies for that long. <b>The Browser stays separate from <code>connect()</code>.</b> Finding a port and connecting to it are two steps the application combines; a connector that does both is a convenience, in a layer around the driver (${D(39)}).`,
      why: 'Each is the protocol as it is: a shared code page nobody states, a timer the client chooses, and a separate protocol from TDS.' },
    { n: 60, s: A, t: 'Always Encrypted: a protocol extension in its own module, over a connection', link: ['done-when', 'm15-always-encrypted'],
      body: `<b>What it is.</b> Always Encrypted is partly TDS and mostly not. MS-TDS defines a login feature (column encryption, versions 1 to 3), a key table and crypto metadata in every COLMETADATA once the feature is negotiated, encrypted parameters with their cipher info, crypto metadata in RETURNVALUE, and an opaque enclave package in RPC and SQL batch requests. The rest is outside TDS: master keys in client-side key stores, column keys the client decrypts, the encryption itself (AEAD_AES_256_CBC_HMAC_SHA256), normalized plaintext, and <code>sp_describe_parameter_encryption</code>, an ordinary stored procedure that says which parameters to encrypt with which key. <b>The split.</b> The core reads and writes every Always Encrypted wire element, with no keys and no cryptography; a connection that negotiated the feature, without the module, shows an encrypted value as it arrives: ciphertext, with its metadata (${D(35)}). <code>tds.encryption</code> holds the keys, the cryptography and the orchestration: protocol capability, not a convenience, and a protocol extension rather than machinery in ${D(27)}’s sense. <b>The facade.</b> A shared <code>Encryption</code> context (key stores, decrypted column keys, describe results) opens or wraps connections and pools whose login asked for column encryption, and refuses one that didn’t, saying why. Its serial channels wrap <code>exchange</code>: they describe a call’s parameters and encrypt them before sending, and decrypt values as they are read, through a decrypt hook the core gives each exchange, so every way of reading a response works unchanged. Composition, not a subclass of <code>Connection</code>. <b>The cryptography dependency:</b> the <code>cryptography</code> package, as an optional extra, behind a small interface another backend could replace; the core stays without dependencies. <b>Key stores in M15:</b> a local key store, an RSA key file; Azure Key Vault and the Windows certificate store come with M17. <b>Enclaves are deferred to the Azure work:</b> the core carries the enclave package as opaque bytes. <b>Tested, level one (pass 1 of ${D(61)}):</b> what the driver writes, it reads back exactly (${D(48)}). Level two, matching Microsoft’s implementation, is pass 2 of ${D(61)}. <b>Observed locally:</b> the server accepts a master key with any key store name and a column key with any encrypted value, since it never decrypts keys; without the login feature, encrypted columns arrive as <code>varbinary</code> ciphertext.`,
      why: 'It is complex enough, and has enough real alternative implementations (key stores, cryptography libraries, attestation protocols), to be a module of its own; the wire elements stay in the core because negotiating the feature changes every result on the connection.' },
    { n: 61, s: A, t: 'Always Encrypted is tested in two passes: the driver’s own round trip, then against .NET',
      body: '<b>Pass 1:</b> what the driver writes, it reads back exactly (D-48). <b>Pass 2:</b> .NET’s SqlClient, with a custom key store, in the .NET SDK container the CLR tests already use, reads what the driver wrote, and the driver reads what SqlClient wrote, for every type. Both passes are part of M15.',
      why: 'MS-TDS names the normalization version, but not how each type’s plaintext is laid out, and the server never sees plaintext, so a difference from Microsoft’s drivers passes every test of reading back what the driver wrote. It shows only when another client reads the driver’s data: each misreads what the other wrote, and a lookup on a deterministic column compares ciphertexts, so it finds no rows rather than failing.' },
    { n: 55, s: A, t: 'Windows and federated logins take a token producer from the application', link: ['ref/conversations', 'what-each-way-of-logging-in-needs--built-d-54-d-55'],
      body: `<b>The driver carries each login’s token exchange as TDS defines it,</b> and nothing else: where tokens go in the hello, the login, the server’s challenges and the client’s answers. <b>The application gives the tokens:</b> a small object that produces them (the first token, then one answer to each of the server’s challenges), or, for a federated login, the token itself or a function that fetches one when the server says where from. <b>Adapters for particular libraries live outside the core,</b> as optional extras: Kerberos and NTLM through a SPNEGO library, Entra ID tokens through Azure’s identity library. <code>tds</code> itself keeps no dependencies (${D(39)}).`,
      why: 'Each library has its own ways of finding credentials, caching and prompting, which are the application’s concern; the protocol’s part is the same whatever library makes the tokens.' },
    { n: 62, s: A, t: 'Azure test infrastructure: Terraform, one resource group, deleted after testing', link: ['build', '4-milestones'],
      body: `<b>M17 and M18 are built together,</b> before M16: the logins are core, the conveniences aren’t. They share one set of infrastructure, created once and deleted once. <b>Terraform describes it,</b> in <code>infra/azure/</code>: one resource group in a subscription given when it’s applied, region East US 2, tagged as temporary; its state stays local, and no secret is ever printed. <b>What it holds:</b> an Azure SQL logical server and databases (Entra admin: the person running it; connection policy Redirect, so routing happens from outside Azure too; one database with an enclave, for Always Encrypted with enclaves); a network open only to the developer’s address; a Windows Server domain controller; SQL Server 2022 Developer on Windows, joined to the domain, with the Browser running; a small Linux VM in the network, from which the Kerberos tests run; a Key Vault with an RSA key, as an Always Encrypted master key. <b>Cost guards:</b> the VMs shut down each night; the cost is checked against Azure’s prices before applying, and <code>terraform plan</code> is shown before anything is created. <b>Deleted after testing:</b> <code>terraform destroy</code>, then a check that the resource group is gone.`,
      why: 'Windows logins need a domain and SQL Server on Windows, federated logins need Entra ID and Azure SQL, and none of it should remain after the tests.' },
    { n: 65, s: A, t: 'Finish Rust locally, validate Windows authentication on transient GCP, then destroy', link: ['roadmap', 'rust-completion-sequence--agreed-2026-10-18-d-65'],
      body: `Agreed 2026-10-18. Finish local Rust work including local-key Always Encrypted and independent .NET interoperability. Add parallel Terraform tooling under <code>infra/gcp/</code>; create the Windows/domain lab only for the Windows NTLM/Kerberos campaign, retain evidence, then verify full teardown. Preserve the historical Azure setup. Entra, Azure-specific features/providers, Windows certificate-store key-provider support and enclaves/attestation are deferred. Require an explicit project, current cost estimate, finite window and expiry fallback. Affected API/provider designs remain to be agreed. This is scoped completion, not Python parity or a deployment claim. M16 follows completion; publication is separate.`,
      why: 'GCP is accessible from the current development location. Windows authentication needs real Windows/domain acceptance, while cloud resources should exist only for the test campaign.' },
    { n: 64, s: P, t: 'Rust channels use movable authority rather than task identity', link: ['rust', '1-ownership-and-permissions-come-first'],
      body: `Proposed direction selected by the user, 2026-10-17. One non-<code>Clone</code> send/read authority moves between owners and lends exclusive borrows. Sequential use after a valid move or loan does not require a task-identity check. This deliberately varies ${D(21)} for Rust; Python retains its opening-task check and <code>hand_over(task)</code>. Separate generation-scoped cancel/close handles may be shared. Busy, continuation, lease and generation checks remain necessary after drop. Exact API, active-response transfer and <code>Send</code> bounds remain R0 choices. No runtime, TLS or cleanup mechanism is selected.`,
      why: 'The user chose to propose Rust moves and borrowing while preserving one advancing reader, safe pool return, explicit cleanup and shared-session semantics.' },
    { n: 63, s: A, t: 'The roadmap after M18: Rust, Python conveniences, application drivers', link: ['roadmap', 'the-phases'],
      body: `<b>Order revised by the user, 2026-10-17:</b> (1) <b>a Rust client:</b> the same design and learning intent, using Python code and tests as a reference; begin with local SQL Server setup, Python tests, source analysis and a plan that establishes ownership and permissions; (2) <b>Python conveniences</b> (M16, ${D(37)}, ${D(38)}, ${D(50)}); (3) <b>application drivers:</b> DB-API 2.0 and possibly other interfaces, built on the conveniences. Rust does not depend on M16. Phase 3 depends on phase 2. <b>Each phase’s design is agreed before code.</b> The ${L('rust', 'Rust development plan')} is a proposal; runtime, APIs, ownership enforcement and exact representations remain open. Accepted milestones are then added to ${L('done-when', 'Done When')}. The ${L('python-baseline', 'Python baseline')} separates fresh evidence from skipped checks. ${D(25)} and ${D(26)} remain deferred to phase 3.`,
      why: 'The user requested Rust first. A second language tests whether the design depends on Python. The existing implementation provides a concrete reference without requiring its convenience layer to be finished. Rust must preserve the learning purpose while making ownership, permissions, exact values and cleanup explicit.' },
    { n: 6, s: A, t: 'Vocabulary', body: `The ${L('model', 'Model’s vocabulary', 'vocabulary')}.`, why: 'Each term names one layer, so any byte can be placed by asking “which layer?”.' },
    { n: 7, s: A, t: 'Plain names', body: 'Docs, code and output use plain names (<i>packet size</i>, <i>session id</i>). MS-TDS names (<code>PacketSize</code>, <code>SPID</code>) appear only in one reference-table column.' },
    { n: 13, s: A, t: 'Step names', link: ['ref/connect', 'shape'], body: '<i>start · secure · hello · log in · ready · routed · closed</i>, rather than MS-TDS’s long state names. They map one-to-one.' },
    { n: 14, s: A, t: 'Worked examples use the spec’s own bytes', body: 'Where no sample exists, construct the bytes and label them.',
      why: 'Readers can check against an independent authority. Cost: the samples come from a TDS 7.2 client, so a note on what this client sends differently is needed.' },
    { n: 15, s: A, t: 'Diagrams as plain text; byte layouts as tables', body: '',
      why: 'They render everywhere: viewers, terminals, code comments. Mermaid is the alternative.' },
    { n: 16, s: A, t: 'Location', body: '<code>docs/design/</code>, numbered in reading order.' },
    { n: 25, s: X, t: 'DB-API layer: how long a serial channel lives', body: 'Deferred 2026-10-16, with DB-API.',
      table: table(['Option', 'For', 'Against'], [
        ['<b>a.</b> One per result, opened by <code>execute()</code>', 'Pool hand-offs between threads work without extra steps; misuse during a result fails every time; free without MARS', 'Extra packets per query under MARS'],
        ['<b>b.</b> One per pool check-out', 'Fewest opens; misuse caught for the whole check-out', 'Needs a pool hook; hand-offs outside a pool break'],
        ['<b>c.</b> One per cursor', 'One-to-one mapping; natural under MARS', 'Without MARS only one cursor can exist at a time'],
        ['<b>d.</b> One per connection, moved when idle', 'Most compatible', 'Misuse detection depends on timing again'],
      ], 'compact') },
    { n: 26, s: X, t: 'DB-API layer: cursor B runs while cursor A has unread rows', body: 'Deferred 2026-10-16, with DB-API.',
      table: table(['Option', 'For', 'Against'], [
        ['<b>a.</b> Fail', `Hides nothing; consistent with ${D(22)}`, 'Surprises users of drivers with independent cursors'],
        ['<b>b.</b> Buffer A, then run B', 'Works with most existing code', 'Hidden memory and latency; needs a size limit'],
        ['<b>c.</b> Always buffer whole results', 'Simplest semantics', 'No streaming; memory grows with result size'],
        ['<b>d.</b> MARS: a serial channel per cursor', 'True streaming independence', 'Requires MARS and its shared-state semantics'],
        ['<b>e.</b> Configurable', 'Fits different workloads', 'More to test; still needs a default'],
      ], 'compact') },
    { n: 30, s: A, t: 'Code layout', body: '<code>clients/python/tds/</code>, one file per concept, mirroring the reference pages. As built: <code>wire</code> (machinery) · <code>packet</code> · <code>prelogin</code> · <code>login7</code> · <code>tokens</code> · <code>types</code> · <code>collations</code> · <code>requests</code> · <code>transactions</code> · <code>response</code> · <code>session</code> · <code>observe</code> · <code>capture</code> · <code>browser</code> · <code>connection/{core,shell}</code> · <code>encryption/{cell,keys,normalize,context,backend}</code> (Always Encrypted, D-60) · <code>__main__</code> (the command-line tool). A file exists only if it holds one concept a reader would look for: no <code>utils</code>, <code>constants</code> or <code>errors</code> modules, and no empty modules for future slices. Errors live next to what raises them. (Proposed with <code>datatypes</code> and <code>batch</code>; D-45 named them <code>types</code> and <code>requests</code>.)' },
    { n: 32, s: A, t: 'TLS runs in the core', body: 'Python’s TLS engine works entirely in memory (<code>ssl.MemoryBIO</code>), so the core drives the handshake and the shell only moves socket bytes. This refines D-24’s first design.' },
    { n: 38, s: A, t: 'Two entry points with the same shape',
      body: '<code>tds.connect()</code> gives one <code>Connection</code>; <code>tds.Pool()</code> lends <code>Connection</code>s. Code that uses a connection is the same either way.' },
  ];

  const card = (r) => `<article class="card" id="d-${r.n}" data-status="${r.s}">
      <h3><span class="card-id">D-${r.n}</span>${r.t}${badge(r.s)}${r.link ? `<span style="margin-left:auto;font-weight:400;font-size:13px">${L(r.link[0], 'Explained ›', r.link[1])}</span>` : ''}</h3>
      ${r.body ? `<p>${r.body}</p>` : ''}
      ${r.table || ''}
      ${r.why ? `<p class="why"><b>Why:</b> ${r.why}</p>` : ''}
    </article>`;

  window.TDS.page({
    id: 'decisions', group: 'Design', num: '4', kind: 'decision',
    title: 'Decisions',
    where: 'The record of what is settled and what is still a proposal.',
    outcome: 'see what is agreed, proposed or open, and why, then agree or change it.',
    body: () => {
      const counts = { [A]: 0, [P]: 0, [O]: 0, [X]: 0 };
      records.forEach((r) => counts[r.s]++);
      return `
        <p><b>Agreed</b> means decided together. <b>Proposed</b> means suggested and waiting for approval. <b>Open</b> means it needs a decision; a suggestion is offered. <b>Deferred</b> means outside this project, kept for whoever builds it.
        Numbers are permanent IDs, so gaps are expected.</p>
        <div class="filters" role="group" aria-label="Filter by status">
          <button class="filter on" data-f="all">All · ${records.length}</button>
          <button class="filter" data-f="${A}">Agreed · ${counts[A]}</button>
          <button class="filter" data-f="${P}">Proposed · ${counts[P]}</button>
          <button class="filter" data-f="${O}">Open · ${counts[O]}</button>
          <button class="filter" data-f="${X}">Deferred · ${counts[X]}</button>
        </div>
        <div class="cards">${records.filter((r) => r.s !== X).map(card).join('')}</div>
        <h2>Deferred</h2>
        <p>Deferred 2026-10-16 to the DB-API driver, which is phase 3 of the ${L('roadmap', 'Roadmap')} (${D(63)}): a package that depends on this driver (${D(39)}). These questions are decided when phase 3 starts.</p>
        <div class="cards">${records.filter((r) => r.s === X).map(card).join('')}</div>`;
    },
    after: (main) => {
      const bar = main.querySelector('.filters');
      bar.addEventListener('click', (e) => {
        const b = e.target.closest('.filter');
        if (!b) return;
        bar.querySelectorAll('.filter').forEach((x) => x.classList.toggle('on', x === b));
        main.querySelectorAll('.card').forEach((c) => (c.hidden = b.dataset.f !== 'all' && c.dataset.status !== b.dataset.f));
      });
    },
  });
})();
